#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step168-$TS"
echo "==> step168: trials WhatsApp-only gate + claimed-only-if-delivered + discount badge"
mkdir -p "$BK/views" "$BK/routes"
cp "$GSZ/views/trials.ejs"     "$BK/views/"  2>/dev/null || true
cp "$GSZ/views/product.ejs"    "$BK/views/"  2>/dev/null || true
cp "$GSZ/routes/trials.js"     "$BK/routes/" 2>/dev/null || true
echo "    backup: $BK"
restore(){ echo "!! error — restoring"; cp "$BK/views/trials.ejs" "$GSZ/views/" 2>/dev/null||true; cp "$BK/views/product.ejs" "$GSZ/views/" 2>/dev/null||true; cp "$BK/routes/trials.js" "$GSZ/routes/" 2>/dev/null||true; }
trap 'restore' ERR
PATCHER=$(mktemp /tmp/patch_step168.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying"; NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"
echo "==> validating"
node --check "$GSZ/routes/trials.js"
for v in views/trials.ejs views/product.ejs; do NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$GSZ/'+'$v','utf8'),{filename:'$GSZ/'+'$v'});"; done
echo "    node --check + ejs ok"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE after ${i}s"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$PATCHER"; trap - ERR
echo ""
echo "==> step168 OK  /trials now needs only WhatsApp (no email). A trial counts as claimed only once it actually delivers — a failed or stuck trial frees up to claim again. Discount badge no longer clips the screen edge. Hard-refresh once."
